mapper.sql:
SELECT i.article_id AS articleId, i.title AS title, i.category_id AS categoryId, i.category_name AS categoryName, i.publish_time AS publishTime, i.article_update_time AS articleUpdateTime, i.live_file_id AS liveFileId, d.id AS docId, d.status AS docStatus, d.chunk_count AS chunkCount, d.update_time AS lastIngestTime, CASE WHEN d.id IS NULL THEN 'UNINGESTED' WHEN d.status = 4 THEN 'INVALID' WHEN d.content_version = i.live_file_id THEN 'INGESTED' ELSE 'STALE' END AS ingestState FROM knowledge_article_index i LEFT JOIN knowledge_doc d ON d.source = 1 AND d.source_id = i.article_id AND d.deleted = 0 WHERE i.deleted = 0
AND i.title LIKE CONCAT('%', #{keyword}, '%')
AND i.category_id = #{categoryId}
AND (CASE WHEN d.id IS NULL THEN 'UNINGESTED' WHEN d.status = 4 THEN 'INVALID' WHEN d.content_version = i.live_file_id THEN 'INGESTED' ELSE 'STALE' END) = #{ingestState}

mapper.select:
SELECT COUNT(*) FROM knowledge_article_index i LEFT JOIN knowledge_doc d ON d.source = 1 AND d.source_id = i.article_id AND d.deleted = 0 WHERE i.deleted = 0
AND i.title LIKE CONCAT('%', #{keyword}, '%')
AND i.category_id = #{categoryId}
AND (CASE WHEN d.id IS NULL THEN 'UNINGESTED' WHEN d.status = 4 THEN 'INVALID' WHEN d.content_version = i.live_file_id THEN 'INGESTED' ELSE 'STALE' END) = #{ingestState}
